'use client'
import { useEffect, useRef, useState } from 'react'
import { prefersReduced, SWAP_CSS, swapLeaveMs, swapTo, type SwapItem } from '@/lib/text-swap'
import { cn } from '@/lib/cn'

// The site's animated value swap (pages/Pricing/Swap): a price, a plan name or a sort label that changes in place. The
// old value rises 12px and fades out while the new one rises in from below, in one grid cell clipped 4px out, over
// 480ms on the loop curve; a value that changes again mid-swap takes over from where it is. `unit` follows the value in
// small muted type ("/month"), `tag` as a small White badge ("Save 20%", the plan badge's look). The type comes from the page (`className`). With
// reduced motion the value changes at once. The leaving value is hidden from assistive tech.
export interface TextSwapProps {
  text: string
  /** Small muted text after the value ("/month"). */
  unit?: string
  /** A small badge after the value ("Save 20%"). */
  tag?: string
  className?: string
}

export function TextSwap({ text, unit, tag, className }: TextSwapProps) {
  const ref = useRef<HTMLSpanElement>(null)
  const [items, setItems] = useState<SwapItem[]>([{ id: 0, text, unit, tag, state: 'in' }])
  const [asked, setAsked] = useState({ text, unit, tag })
  const dropAt = useRef(new Map<number, number>())

  if (asked.text !== text || asked.unit !== unit || asked.tag !== tag) {
    setAsked({ text, unit, tag })
    setItems(swapTo(items, { text, unit, tag }, prefersReduced()))
  }

  useEffect(() => {
    let frame = 0
    if (items.some((i) => i.state === 'enter')) {
      frame = requestAnimationFrame(() => {
        frame = requestAnimationFrame(() => setItems((now) => now.map((i) => (i.state === 'enter' ? { ...i, state: 'in' as const } : i))))
      })
    }
    const now = performance.now()
    const leaving = items.filter((i) => i.state === 'out')
    const live = new Set(leaving.map((i) => i.id))
    for (const id of dropAt.current.keys()) if (!live.has(id)) dropAt.current.delete(id)
    const ms = ref.current ? swapLeaveMs(ref.current) : 480
    for (const i of leaving) if (!dropAt.current.has(i.id)) dropAt.current.set(i.id, now + ms)
    let timer = 0
    if (leaving.length) {
      const due = Math.min(...leaving.map((i) => dropAt.current.get(i.id) ?? now))
      timer = window.setTimeout(() => {
        const t = performance.now()
        const done = new Set(leaving.filter((i) => (dropAt.current.get(i.id) ?? 0) <= t).map((i) => i.id))
        setItems((cur) => cur.filter((c) => !done.has(c.id)))
      }, Math.max(0, due - now))
    }
    return () => {
      cancelAnimationFrame(frame)
      clearTimeout(timer)
    }
  }, [items])

  return (
    <span ref={ref} data-ds="text-swap" className={cn('inline-grid overflow-clip align-top [overflow-clip-margin:var(--ds-space-xs)]', className)}>
      <style href="ds-text-swap" precedence="ds">{SWAP_CSS}</style>
      {items.map((item) => (
        <span key={item.id} className="ds-swap-item" data-state={item.state} aria-hidden={item.state === 'out' || undefined}>
          {item.text}
          {item.unit ? <span className="ms-2 font-text text-ui/5 text-fg-muted">{item.unit}</span> : null}
          {item.tag ? <span className="relative ms-2 inline-block rounded-ds-sm bg-action-primary px-2 py-1 font-text text-caption/5 font-medium whitespace-nowrap text-action-primary-fg">{item.tag}</span> : null}
        </span>
      ))}
    </span>
  )
}

export default TextSwap

import { Fragment } from 'react'
import { cn } from '@/lib/cn'

// The site's sentence keeper (ui/Sentences): a line of copy split after each sentence, so below 768 each sentence wraps
// as a whole (inline-block) instead of leaving one word alone on a line; wider, it reads as plain text.
export interface SentencesProps {
  text: string
  className?: string
}

export function Sentences({ text, className }: SentencesProps) {
  const parts = text.split(/(?<=[.!?])\s+/)
  return (
    <span data-ds="sentences" className={cn('contents', className)}>
      {parts.map((part, i) => (
        <Fragment key={`${i}-${part}`}>
          {i > 0 ? ' ' : null}
          <span className="max-md:inline-block">{part}</span>
        </Fragment>
      ))}
    </span>
  )
}

export default Sentences

// The site's value swap (pages/Pricing/Swap): when the text changes, the old value rises 12px and fades out while the
// new one rises in from 12px below, both in one grid cell, over --ds-duration-slow on the loop curve. Both flavors keep
// their list of values with this, and share the CSS. With reduced motion the new value replaces the old at once.
export type SwapState = 'enter' | 'in' | 'out'
export interface SwapValue { text: string, unit?: string, tag?: string }
export interface SwapItem extends SwapValue { id: number, state: SwapState }

const same = (a: SwapValue | undefined, b: SwapValue) => !!a && a.text === b.text && a.unit === b.unit && a.tag === b.tag

/** The list after the value changes to `next`: the shown value leaves and `next` enters (or replaces it, reduced). */
export function swapTo(items: SwapItem[], next: SwapValue, reduced: boolean): SwapItem[] {
	if (same(items.find((i) => i.state !== 'out'), next)) return items
	const id = items.reduce((max, i) => Math.max(max, i.id), 0) + 1
	if (reduced) return [{ id, ...next, state: 'in' }]
	return [...items.map((i) => (i.state === 'out' ? i : { ...i, state: 'out' as const })), { id, ...next, state: 'enter' as const }]
}

export const prefersReduced = () => !!globalThis.matchMedia && globalThis.matchMedia('(prefers-reduced-motion: reduce)').matches

/** How long a leaving value stays: the swap's duration token, in ms. */
export function swapLeaveMs(el: Element): number {
	const v = getComputedStyle(el).getPropertyValue('--ds-duration-slow').trim()
	const n = parseFloat(v)
	return Number.isFinite(n) && n > 0 ? n * (v.endsWith('ms') ? 1 : 1000) : 480
}

export const SWAP_CSS = `
.ds-swap-item { grid-area: 1 / 1; white-space: nowrap; transition: opacity var(--ds-duration-slow) var(--ds-easing-loop), translate var(--ds-duration-slow) var(--ds-easing-loop); }
.ds-swap-item[data-state="enter"] { opacity: 0; translate: 0 var(--ds-space-md); transition: none; }
.ds-swap-item[data-state="out"] { opacity: 0; translate: 0 calc(-1 * var(--ds-space-md)); }
@media (prefers-reduced-motion: reduce) { .ds-swap-item { transition: none; } }
`

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
